import { Controller, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr029112X345a2bController {
  @Patch('/approval-documents/:approvalDocumentId/designation')
  async updateApprovalDocumentDesignation(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const approvalDocumentId = req.params['approvalDocumentId'];
    if (!/^[0-9]+$/.test(approvalDocumentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서 ID 형식이 올바르지 않습니다.');
    }
    const isUrgent = data['isUrgent'];
    const isSecret = data['isSecret'];
    if (isUrgent !== undefined && isUrgent !== null && typeof isUrgent !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '긴급결재 여부는 true 또는 false여야 합니다.');
    }
    if (isSecret !== undefined && isSecret !== null && typeof isSecret !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '보안문서 여부는 true 또는 false여야 합니다.');
    }
    const urgentValue = typeof isUrgent === 'boolean' ? isUrgent : null;
    const secretValue = typeof isSecret === 'boolean' ? isSecret : null;
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT drafter_id AS "drafterId" FROM approval_document WHERE approval_document_id = CAST(:id AS bigint)',
        { id: approvalDocumentId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '대상 결재문서를 찾을 수 없습니다.');
      }
      if (String(found[0]['drafterId']) !== String(user.id)) {
        throw new ApiError(422, 'NOT_DOCUMENT_DRAFTER', '문서 기안자만 지정을 변경할 수 있습니다.');
      }
      const rows = await db.query(
        'UPDATE approval_document SET is_urgent = COALESCE(CAST(:isUrgent AS boolean), is_urgent), is_secret = COALESCE(CAST(:isSecret AS boolean), is_secret), updated_at = now() WHERE approval_document_id = CAST(:id AS bigint) RETURNING approval_document_id AS "approvalDocumentId", is_urgent AS "isUrgent", is_secret AS "isSecret"',
        { id: approvalDocumentId, isUrgent: urgentValue, isSecret: secretValue },
      );
      return rows[0];
    });
  }
}

