import { useState } from 'react';
import { call, useData, Badge, DateText, Band, DataTable, Pager, Drawer, Pairs, Form, Field, Select, LookupSelect, RefName, Filters, Tiles } from '../kit';
import type { PageProps, Row, Page } from '../kit';

export default function FnSfr029112X345a2bPage({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [statusFilter, setStatusFilter] = useState('');
  const [selected, setSelected] = useState<Row | null>(null);
  const [isUrgent, setIsUrgent] = useState('false');
  const [isSecret, setIsSecret] = useState('false');
  const [done, setDone] = useState<Row[]>([]);
  const [docId, setDocId] = useState<number | string>('');
  const [open, setOpen] = useState(false);

  const yesNo: [string, string][] = [['true', '지정'], ['false', '해제']];

  const urgentCount = done.filter((r) => r['isUrgent'] === true).length;
  const secretCount = done.filter((r) => r['isSecret'] === true).length;

  const startNew = () => {
    setDocId('');
    setIsUrgent('false');
    setIsSecret('false');
    setOpen(true);
  };

  const submit = async () => {
    if (docId === '' || docId === null || docId === undefined) {
      throw new Error('결재문서를 선택하세요.');
    }
    const result = await call('PATCH', '/approval-documents/' + docId + '/designation', role, {
      isUrgent: isUrgent === 'true',
      isSecret: isSecret === 'true',
    });
    setDone([result, ...done.filter((r) => r['approvalDocumentId'] !== result['approvalDocumentId'])]);
    setOpen(false);
    notify('지정을 변경했습니다.');
  };

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>긴급결재</h2>
        <Tiles items={[['긴급 지정 문서', urgentCount]]} />
      </section>
      <section className="box span-4">
        <h2>보안문서</h2>
        <Tiles items={[['보안 지정 문서', secretCount]]} />
      </section>
      <section className="box span-4">
        <h2>지정 변경</h2>
        <Band total={done.length}>
          <button type="button" onClick={startNew}>지정 변경</button>
        </Band>
      </section>
      <section className="box span-12">
        <h2>변경 결과</h2>
        <DataTable
          rows={done}
          empty="변경한 문서가 없습니다."
          onRowClick={(row) => setSelected(row)}
          columns={[
            { key: 'approvalDocumentId', label: '결재문서', render: (r) => <RefName table="approval_document" role={role} value={r['approvalDocumentId']} /> },
            { key: 'isUrgent', label: '긴급결재 여부', render: (r) => <Badge value={r['isUrgent'] ? '긴급' : '일반'} /> },
            { key: 'isSecret', label: '보안문서 여부', render: (r) => <Badge value={r['isSecret'] ? '보안' : '일반'} /> },
          ]}
        />
      </section>
      {open && (
        <Drawer title="긴급결재·보안문서 지정" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="저장">
            <Field label="결재문서 ID" required>
              <LookupSelect table="approval_document" role={role} value={docId} onChange={setDocId} />
            </Field>
            <Field label="긴급결재 여부">
              <Select value={isUrgent} onChange={setIsUrgent} options={yesNo} placeholder="선택" />
            </Field>
            <Field label="보안문서 여부">
              <Select value={isSecret} onChange={setIsSecret} options={yesNo} placeholder="선택" />
            </Field>
          </Form>
        </Drawer>
      )}
      {selected && (
        <Drawer title="지정 결과" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['결재문서 ID', <RefName table="approval_document" role={role} value={selected['approvalDocumentId']} />],
              ['긴급결재 여부', <Badge value={selected['isUrgent'] ? '긴급' : '일반'} />],
              ['보안문서 여부', <Badge value={selected['isSecret'] ? '보안' : '일반'} />],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
